using System;using System.IO;using System.Linq;
namespace IrisDesktop {
 public static class GoalReplacementFixture {
  static readonly string Old="10000000-0000-4000-8000-000000000001";
  static ProgressScope S(){return new ProgressScope{environment="development",accountId="synthetic",characterId="character"};}
  static void Need(bool ok,string why){if(!ok)throw new Exception(why);}
  static ProgressMutation Create(string id){return new ProgressMutation{kind="CreateGoal",scope=S(),goalId=id,sourcePlanId="plan",action="crafting",displayName="wood",targetQuantity=100};}
  static ProgressMutation Replace(string next,int quantity){return ProgressDomain.Serializer().Deserialize<ProgressMutation>("{\"kind\":\"ReplaceEmptyGoal\",\"scope\":{\"environment\":\"development\",\"accountId\":\"synthetic\",\"characterId\":\"character\"},\"goalId\":\""+Old+"\",\"sourcePlanId\":\"plan\",\"action\":\"crafting\",\"displayName\":\"wood\",\"targetQuantity\":100,\"replacement\":{\"goalId\":\""+next+"\",\"targetQuantity\":"+quantity+"}}");}
  static DesktopErgonProgressStore Seed(string root){var s=new DesktopErgonProgressStore(root,"development");Need(s.Commit(Create(Old),0,Guid.NewGuid()).status=="committed","seed");return s;}
  sealed class FaultIO:IProgressFileIO {
   readonly ProgressFileIO real=new ProgressFileIO();internal bool fail;
   public byte[] ReadCipher(string p,int max){return real.ReadCipher(p,max);}public void WriteNewAndFlush(string p,byte[] b){if(fail)throw new IOException("synthetic full");real.WriteNewAndFlush(p,b);}public void ReplaceWithBackup(string t,string p,string b){real.ReplaceWithBackup(t,p,b);}public void MoveNew(string t,string p){real.MoveNew(t,p);}public IDisposable AcquireExclusiveLock(string p){return real.AcquireExclusiveLock(p);}
  }
  public static void Run(string root){
   var store=Seed(Path.Combine(root,"main"));var op=Guid.NewGuid();var next=op.ToString("D");var mutation=Replace(next,70);var ack=store.Commit(mutation,1,op);Need(ack.status=="committed","R01 atomic replacement expected committed: "+ack.error);var view=store.Load(S()).view;Need(view.revision==2&&view.goals.Count(g=>g.lifecycle=="active")==1&&view.goals.Single(g=>g.goalId==Old).targetQuantity==100&&view.goals.Single(g=>g.goalId==Old).detached&&view.goals.Single(g=>g.goalId==Old).lifecycle=="cancelled"&&view.goals.Single(g=>g.goalId==next).remainingQuantity==70,"R01 view");
   using(var w=store.AcquireWriter(new ProgressLockOwner())){var d=store.Inspect(w);Need(d.auditEvents.Count==2&&d.auditEvents[1].operationId==next,"R01 audit");}
   Console.WriteLine("PASS R01 single atomic event preserves original and creates exactly one replacement");
   var reopen=new DesktopErgonProgressStore(Path.Combine(root,"main"),"development");Need(reopen.Commit(mutation,1,op).status=="already-applied"&&reopen.Load(S()).view.goals.Length==2,"R02 replay");Need(reopen.Commit(Replace(next,60),1,op).status=="conflict","R02 meaning");Need(reopen.Commit(Replace(Guid.NewGuid().ToString("D"),60),1,Guid.NewGuid()).status=="conflict","R02 CAS");Need(reopen.Commit(Replace(Guid.NewGuid().ToString("D"),60),2,Guid.NewGuid()).status=="rejected","R02 old inactive");Console.WriteLine("PASS R02 restart, duplicate operation, changed meaning and competing replacement cannot duplicate");
   Need(reopen.Commit(Create(Guid.NewGuid().ToString("D")),2,Guid.NewGuid()).status=="rejected","R03 create bypass");Need(reopen.Commit(new ProgressMutation{kind="SetLifecycle",scope=S(),goalId=Old,lifecycle="active"},2,Guid.NewGuid()).status=="rejected","R03 revive");Console.WriteLine("PASS R03 old CreateGoal and lifecycle cannot bypass active root uniqueness");
   foreach(var mode in new[]{"foreign","quantity","request","child","paused","unknown"}){
    var s=Seed(Path.Combine(root,mode));long revision=1;var m=Replace(Guid.NewGuid().ToString("D"),70);
    if(mode=="foreign")m.scope.characterId="other";if(mode=="quantity")m.targetQuantity=99;
    if(mode=="paused"){Need(s.Commit(new ProgressMutation{kind="SetLifecycle",scope=S(),goalId=Old,lifecycle="paused"},1,Guid.NewGuid()).status=="committed","pause seed");revision++;}
    if(mode=="request"||mode=="unknown"){Need(s.Commit(new ProgressMutation{kind="BindPreparedRequest",scope=S(),goalId=Old,requestId=Guid.NewGuid().ToString("D"),action="crafting",displayName="wood",craftCount=1,outputPerCraft=1,expectedOutput=1,preparedAt=1,expiresAt=2},1,Guid.NewGuid()).status=="committed","request seed");revision++;}
    if(mode=="child"){var c=Create(Guid.NewGuid().ToString("D"));c.parentGoalId=Old;Need(s.Commit(c,1,Guid.NewGuid()).status=="committed","child seed");revision++;}
    var before=File.ReadAllBytes(s.FilePath);Need(s.Commit(m,revision,Guid.NewGuid()).status=="rejected"&&before.SequenceEqual(File.ReadAllBytes(s.FilePath)),"R04 "+mode);
   }Console.WriteLine("PASS R04 foreign owner, wrong old quantity, requests, child, paused and unresolved blocked unchanged");
   // A historical v1 document did not serialize the new nullable mutation member.
   var legacy=Seed(Path.Combine(root,"legacy"));var cipher=File.ReadAllBytes(legacy.FilePath);var entropy=ProgressDomain.Utf8.GetBytes("SANCTUM:IRIS:ErgonProgress:v1:development");var plain=System.Security.Cryptography.ProtectedData.Unprotect(cipher,entropy,System.Security.Cryptography.DataProtectionScope.CurrentUser);var text=ProgressDomain.Utf8.GetString(plain).Replace(",\"replacement\":null","").Replace("\"replacement\":null,","");File.WriteAllBytes(legacy.FilePath,System.Security.Cryptography.ProtectedData.Protect(ProgressDomain.Utf8.GetBytes(text),entropy,System.Security.Cryptography.DataProtectionScope.CurrentUser));Need(legacy.Load(S()).health=="ok","R05 legacy digest");Need(legacy.Commit(Replace(Guid.NewGuid().ToString("D"),70),1,Guid.NewGuid()).status=="committed"&&legacy.Load(S()).health=="ok","R05 legacy replace");Console.WriteLine("PASS R05 prior nullable-free v1 document and replacement audit replay remain readable");
  }
  public static void Faults(string root){
   var io=new FaultIO();var fault=new DesktopErgonProgressStore(Path.Combine(root,"fault"),"development",io);Need(fault.Commit(Create(Old),0,Guid.NewGuid()).status=="committed","fault seed");var retained=File.ReadAllBytes(fault.FilePath);io.fail=true;Need(fault.Commit(Replace(Guid.NewGuid().ToString("D"),70),1,Guid.NewGuid()).status=="unavailable","R07 false ACK");Need(retained.SequenceEqual(File.ReadAllBytes(fault.FilePath))&&fault.Load(S()).view.goals.Single().lifecycle=="active","R07 previous data changed");Console.WriteLine("PASS R07 injected native write failure preserves original ciphertext and active goal");
   var full=Seed(Path.Combine(root,"capacity"));ProgressDocument document;using(var w=full.AcquireWriter(new ProgressLockOwner()))document=full.Inspect(w);for(int i=1;i<ProgressDomain.GoalLimit;i++){var filler=Create(Guid.NewGuid().ToString("D"));filler.sourcePlanId="filler-"+i;var result=ProgressDomain.Commit(document,filler,document.revision,Guid.NewGuid(),1000+i);Need(result.status=="committed","capacity seed");document=result.document;}var entropy=ProgressDomain.Utf8.GetBytes("SANCTUM:IRIS:ErgonProgress:v1:development");File.WriteAllBytes(full.FilePath,System.Security.Cryptography.ProtectedData.Protect(ProgressDomain.Utf8.GetBytes(ProgressDomain.Serialize(document)),entropy,System.Security.Cryptography.DataProtectionScope.CurrentUser));retained=File.ReadAllBytes(full.FilePath);Need(full.Commit(Replace(Guid.NewGuid().ToString("D"),70),document.revision,Guid.NewGuid()).status=="rejected"&&retained.SequenceEqual(File.ReadAllBytes(full.FilePath))&&full.Load(S()).health=="ok","R08 partial replacement at capacity");Console.WriteLine("PASS R08 capacity rejection preserves old goal and history without partial replacement");
  }
  public static void SeedRace(string root){Seed(root);}
  public static void Lineage(string root){
   var s=Seed(Path.Combine(root,"lineage-replaced"));var op=Guid.NewGuid();Need(s.Commit(Replace(op.ToString("D"),70),1,op).status=="committed","lineage replace");var child=Create(Guid.NewGuid().ToString("D"));child.parentGoalId=Old;var before=File.ReadAllBytes(s.FilePath);Need(s.Commit(child,2,Guid.NewGuid()).status=="rejected"&&before.SequenceEqual(File.ReadAllBytes(s.FilePath)),"R09 child under replaced root accepted");Console.WriteLine("PASS R09 replaced old root cannot create a new active child");
  }
  public static void LineageBinding(string root){
   foreach(var mode in new[]{"cancelled","paused"}){
    var existing=Seed(Path.Combine(root,"lineage-"+mode));var child=Create(Guid.NewGuid().ToString("D"));child.parentGoalId=Old;Need(existing.Commit(child,1,Guid.NewGuid()).status=="committed","lineage child seed");Need(existing.Commit(new ProgressMutation{kind="SetLifecycle",scope=S(),goalId=Old,lifecycle=mode},2,Guid.NewGuid()).status=="committed","lineage parent seed");var binding=new ProgressMutation{kind="BindPreparedRequest",scope=S(),goalId=child.goalId,requestId=Guid.NewGuid().ToString("D"),action="crafting",displayName="wood",craftCount=1,outputPerCraft=1,expectedOutput=1,preparedAt=1,expiresAt=2};var before=File.ReadAllBytes(existing.FilePath);Need(existing.Load(S()).health=="ok","legacy lineage unreadable");Need(existing.Commit(binding,3,Guid.NewGuid()).status=="rejected"&&before.SequenceEqual(File.ReadAllBytes(existing.FilePath)),"R10 binding through inactive root accepted "+mode);
   }Console.WriteLine("PASS R10 existing child under paused/cancelled root stays readable but cannot bind a new request");
  }
  public static void Race(string root,int target){var s=new DesktopErgonProgressStore(root,"development");var op=Guid.NewGuid();Console.WriteLine(s.Commit(Replace(op.ToString("D"),target),1,op).status);}
  public static void CheckRace(string root){var s=new DesktopErgonProgressStore(root,"development");var v=s.Load(S());Need(v.health=="ok"&&v.view.revision==2&&v.view.goals.Count(g=>g.lifecycle=="active")==1&&v.view.goals.Length==2,"R06 race");Console.WriteLine("PASS R06 two independent processes produce one CAS winner");}
 }
